// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;

    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 100 ether);

        // actor deposits `amount` via the fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep, "deposit failed");

        // actor withdraws; EOA callee so the low-level call succeeds on both versions
        vm.prank(actor);
        c.withdraw();

        // General rule: after a completed withdrawal the caller's balance is zeroed.
        assertTrue(c.balances(actor) == 0, "balance must be zero after withdrawal");
    }
}
